// Generated by secure-by-design v0.1.0 for AI human-in-the-loop oversight.
// Aligns with ISO/IEC 42001 §8.3 and EU AI Act Art. 14 patterns.
// Reads from ../../privacy-security-manifest.yaml.
// Safe to modify. Safe to delete. Re-run /sbd-deploy to regenerate.
// Docs: docs/scaffolds/human-oversight.md
//
// For AI systems whose manifest declares humanOversight != 'none', any path
// from AI output → user-facing action MUST flow through this gate.

import { auditLog } from '../security/audit_log';

export type OversightLevel = 'none' | 'review-recommended' | 'physician-review-mandatory' | 'expert-review-mandatory';

export interface OversightDecision {
  approver: string;            // identifier of the human who reviewed
  approverRole: string;        // 'physician', 'specialist', 'compliance-officer', etc.
  decision: 'approved' | 'rejected' | 'modified';
  rationale?: string;          // free-text rationale (will be PHI-redacted in logs)
  decidedAt: Date;
  modifications?: Record<string, unknown>; // when decision = 'modified'
}

export interface OversightAdapter {
  /**
   * Request a human review. Implementation could be:
   *  - synchronous (block while a physician approves in UI)
   *  - asynchronous (queue + webhook callback)
   *  - in-line (physician is the actor and clicks "I approve")
   */
  requestReview(input: {
    systemName: string;
    requiredLevel: OversightLevel;
    aiOutput: unknown;
    dataPrincipalId?: string;
  }): Promise<OversightDecision>;
}

let adapter: OversightAdapter | null = null;
export function setOversightAdapter(a: OversightAdapter): void { adapter = a; }

/**
 * Gate function — call after `decisionLog(...)` returns AI output and before
 * persisting / displaying / acting on it.
 *
 * Throws if no adapter is configured (this is intentional — production code
 * with manifested humanOversight MUST have an adapter wired).
 */
export async function requirePhysicianReview<T>(
  systemName: string,
  aiOutput: T,
  options: { dataPrincipalId?: string; level?: OversightLevel } = {},
): Promise<{ output: T; decision: OversightDecision }> {
  const level = options.level ?? 'physician-review-mandatory';

  if (level === 'none') {
    return {
      output: aiOutput,
      decision: {
        approver: 'system',
        approverRole: 'auto',
        decision: 'approved',
        decidedAt: new Date(),
      },
    };
  }

  if (!adapter) {
    throw new Error(
      'secure-by-design: OversightAdapter not configured but oversight level is ' + level +
      '. Either configure an adapter at boot or set the manifest aiSystems[].humanOversight to none.',
    );
  }

  const decision = await adapter.requestReview({
    systemName,
    requiredLevel: level,
    aiOutput,
    dataPrincipalId: options.dataPrincipalId,
  });

  await auditLog.security(`ai.${systemName}.oversight`, {
    actor: decision.approver,
    target: options.dataPrincipalId,
    severity: 'NOTICE',
    outcome: decision.decision === 'rejected' ? 'denied' : 'success',
    attrs: {
      level,
      decision: decision.decision,
      approverRole: decision.approverRole,
      decidedAt: decision.decidedAt.toISOString(),
    },
  });

  if (decision.decision === 'rejected') {
    const err: Error & { statusCode?: number; code?: string } = new Error('AI output rejected on human review.');
    err.statusCode = 451;
    err.code = 'OVERSIGHT_REJECTED';
    throw err;
  }

  if (decision.decision === 'modified' && decision.modifications) {
    return {
      output: { ...(aiOutput as object), ...decision.modifications } as T,
      decision,
    };
  }

  return { output: aiOutput, decision };
}
